update pages set contenu = '{"sections":[]}'::jsonb where path = '/secteurs/aeronautique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance dans l''industrie aéronautique","mecanisme":"Nous entretenons les moyens qui fabriquent : machines d''usinage 3 à 5 axes, lignes d''assemblage, moyens de mesure, utilités. Chaque intervention produit un historique relié à l''équipement, disponible le jour où votre donneur d''ordre audite le site.","cta":"Étudier la maintenance de mes moyens de production","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30, pour qualifier votre besoin et notre périmètre. Astreinte 24/24 et 7/7 en option pour les sites en équipes."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens de précision, automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens au contact des bassins de la filière"}]},{"type":"probleme","punchline":"Une machine qui dérive ne s''arrête pas. Elle continue de produire, et elle produit du rebut.","puces":[{"accroche":"La dérive coûte plus cher que la panne.","texte":"Des pièces à rebuter, parfois à rappeler. La maintenance participe directement à la conformité du produit."},{"accroche":"Chaque pièce doit être reliée aux conditions de sa fabrication.","texte":"Une intervention non documentée sur un moyen de production fragilise cette chaîne."},{"accroche":"Les cadences montent, les fenêtres d''immobilisation se négocient serré.","texte":"Chaque équipement compte quand le palier de production approche."},{"accroche":"L''exigence documentaire descend jusqu''au rang 2","texte":", sans les moyens du donneur d''ordre pour l''absorber."},{"accroche":"Le technicien qui connaît la machine de précision est le profil le plus disputé de la filière.","texte":"Les postes restent ouverts des mois."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Cartographie de criticité","texte":"chaque moyen classé selon son impact et son risque."},"benefice":"Une machine goulot ne se traite pas comme une perceuse d''atelier. Le budget suit la criticité réelle."},{"prestation":{"accroche":"Contrôles géométriques et relevés suivis dans le temps","texte":"broches, axes, changeurs d''outils, lubrification."},"benefice":"La dérive apparaît dans les mesures avant d''apparaître dans les rebuts."},{"prestation":{"accroche":"Préventif calé sur vos fenêtres","texte":"entre les équipes, la nuit, aux arrêts planifiés."},"benefice":"La remise en service du lundi matin ne se découvre pas, elle suit une procédure préparée."},{"prestation":{"accroche":"Automaticiens et roboticiens","texte":"cellules de perçage, de dépose de fibre ou de peinture, variateurs, automates de machines."},"benefice":"La partie commande cesse d''être le point aveugle de l''équipe mécanique."},{"prestation":{"accroche":"Appui sur les moyens de mesure","texte":"machines à mesurer, bancs de test, environnement des salles de métrologie."},"benefice":"La fiabilité des moyens qui libèrent vos pièces est suivie comme le reste du parc."},{"prestation":{"accroche":"Comptes rendus au format de votre GMAO","texte":", habilitations à jour, plan de prévention signé."},"benefice":"Quand l''audit client arrive, l''historique complet par moyen est déjà en place."},{"prestation":{"accroche":"Renforts préparés pour une montée en cadence","texte":"entretien resserré sur les goulots, références critiques anticipées."},"benefice":"Le palier se passe sans découvrir une pièce manquante la semaine où elle bloque tout."},{"prestation":{"texte":"Attendu de la filière"},"benefice":"Réponse Migen"},{"prestation":{"texte":"Conformité des moyens"},"benefice":"Entretien tracé, mesures documentées, dérives signalées"},{"prestation":{"texte":"Temps d''immobilisation"},"benefice":"Interventions préparées, pièces anticipées, fenêtres respectées"},{"prestation":{"texte":"Compétence machines de précision"},"benefice":"Mécaniciens et automaticiens confirmés, évalués en entretien"},{"prestation":{"texte":"Traçabilité"},"benefice":"Historique complet par équipement, intégrable à vos systèmes"},{"prestation":{"texte":"Sécurité"},"benefice":"Habilitations vérifiées, coactivité gérée, accueil sécurité suivi"},{"prestation":{"texte":"Couverture nationale"},"benefice":"4 agences, taux horaire homogène, un seul interlocuteur"}],"prose":[{"texte":"Notre [bureau d''études](/offres/bureau-etudes/) accompagne aussi vos évolutions : reprise d''un poste, mise en conformité d''une machine, adaptation d''une ligne à une nouvelle cadence. Le détail de la spécialité machine se trouve sur notre page [maintenance machine outil](/expertises/mecanique/machine-outil/)."}]},{"type":"deroule","etapes":[{"titre":"Qualification honnête du périmètre","texte":"ce que nous savons couvrir, et ce que nous ne couvrons pas. La réponse arrive au premier échange, pas après la signature."},{"titre":"Cartographie","texte":"criticité, état, moyens goulots, pièces critiques. C''est la photo de départ dont tout le reste découle."},{"titre":"Plan préventif","texte":"fréquences calées sur l''utilisation réelle, opérations positionnées dans vos fenêtres, références anticipées."},{"titre":"Intégration","texte":"habilitations vérifiées, plan de prévention signé, coactivité organisée avec vos équipes et les autres intervenants."},{"titre":"Exécution","texte":"préventif aux fenêtres, dépannage outillé, vérifications et enregistrements systématiques à la remise en route."},{"titre":"Préparation des paliers","texte":"renforts réservés avant la montée en cadence, entretien resserré sur les goulots, retour d''expérience de chaque palier passé."}]}]'::jsonb) where path = '/secteurs/aeronautique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"garanties","puces":[{"accroche":"Un périmètre annoncé sans survente","texte":"la maintenance des aéronefs relève d''un métier réglementé qui n''est pas le nôtre. Nous entretenons les usines qui fabriquent, et nous le disons dès le premier appel."},{"accroche":"La traçabilité complète par moyen de production","texte":"gamme, références, vérifications, intégrables à votre GMAO. Vos auditeurs y trouvent l''historique sans reconstitution."},{"accroche":"Des intervenants dont le niveau se prouve","texte":"10 % des candidats retenus, évaluation technique et comportementale, expérience des machines de précision vérifiée avant l''affectation."}]},{"type":"cta","question":"Besoin de sécuriser vos moyens de production avant le prochain palier de cadence ?","bouton":"Étudier la maintenance de mes moyens de production","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Technicien intégré à temps plein sur centres d''usinage, presses et machines à commande numérique, pièces mécaniques de précision","texte":"en 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Automaticien SIEMENS affecté au démarrage d''une ligne de production neuve","texte":"près de Lyon","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Six techniciens pour l''installation et la mise en production d''un parc machine neuf","texte":"depuis janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"3 à 5 techniciens pour accompagner la montée en cadence de plusieurs usines","texte":"depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"},{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant, sans rachat de matériel neuf","texte":"Lyon, février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"}]},{"type":"objections","questions":[{"question":"Faites-vous de la maintenance aéronautique au sens MRO ?","reponse":"Non. L''entretien des avions, en ligne comme en hangar, relève de l''aviation civile et de la réglementation Part 145, avec des agréments spécifiques. Notre métier est la maintenance des équipements industriels des usines qui fabriquent pour la filière."},{"question":"Vos interventions respectent-elles nos exigences de traçabilité ?","reponse":"Oui : chaque opération produit un compte rendu détaillé, gamme, références, vérifications, intégrable à votre GMAO. Vos auditeurs y trouvent l''historique complet de chaque moyen, sans reconstitution."},{"question":"Pouvez-vous suivre une montée en cadence ?","reponse":"Oui, et cela se prépare avec vous : renfort de techniciens à l''approche des paliers, entretien resserré sur les moyens goulots, références critiques anticipées. La montée se réussit avant, pas pendant."},{"question":"Intervenez-vous sur les machines à commande numérique ?","reponse":"Oui : géométrie, broches, axes, changeurs d''outils, variateurs, automates de machines. Nos mécaniciens de précision et nos automaticiens travaillent ensemble sur ces moyens, avec les constructeurs quand l''expertise l''impose."},{"question":"Travaillez-vous pour les sous-traitants comme pour les grands sites ?","reponse":"Oui. Le rang dans la chaîne ne change pas l''exigence, seulement les moyens disponibles pour l''absorber. Pour une PME de la filière, le technicien intégré ou l''abonnement remplacent une équipe interne difficile à recruter."},{"question":"Où intervenez-vous ?","reponse":"Partout en France : Toulouse et l''Occitanie, les Pays de la Loire, l''Île-de-France, le Grand Est, la région lyonnaise et les Alpes industrielles. 4 agences, un taux horaire homogène, un interlocuteur unique pour les groupes multi-sites."}]},{"type":"ctaFinal","question":"Besoin d''un entretien de vos moyens à la hauteur de ce que vous fabriquez ?","bouton":"Parler à un chargé d''affaires","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/secteurs/aeronautique/';
